/// drm_get_panel_orientation_quirk - Check for panel orientation quirks
/// @width: width in pixels of the panel
/// @height: height in pixels of the panel
///
/// This function checks for platform specific (e.g. DMI based) quirks
/// providing info on panel_orientation for systems where this cannot be
/// probed from the hard-/firm-ware. To avoid false-positive this function
/// takes the panel resolution as argument and checks that against the
/// resolution expected by the quirk-table entry.
///
/// Note this function is also used outside of the drm-subsys, by for example
/// the efifb code. Because of this this function gets compiled into its own
/// kernel-module when built as a module.
///
/// Returns:
/// A DRM_MODE_PANEL_ORIENTATION_* value if there is a quirk for this system,
/// or DRM_MODE_PANEL_ORIENTATION_UNKNOWN if there is no quirk.
#[unsafe(no_mangle)]
#[unsafe(link_section = ".text.slate_distinct.drm_panel_orientation_quirks.drm_get_panel_orientation_quirk")]
extern "C" fn drm_get_panel_orientation_quirk(width: i32, height: i32) -> i32 {
let mut r#match: *const dmi_system_id = unsafe { core::mem::zeroed() };
let mut i: i32 = 0;
r#match = unsafe { dmi_first_match(core::ptr::addr_of!(orientation_data.0) as *const dmi_system_id) };
while !r#match.is_null() {
let data: *const drm_dmi_panel_orientation_data = (unsafe { (*r#match).driver_data }) as *const drm_dmi_panel_orientation_data;
if !((unsafe { (*data).width }) != width || (unsafe { (*data).height }) != height) {
if unsafe { (*data).bios_dates }.is_null() {
return unsafe { (*data).orientation };
}
let bios_date: *const u8 = unsafe { dmi_get_system_info(3i32) };
if !bios_date.is_null() {
i = unsafe { match_string((*data).bios_dates, 1i32.wrapping_neg() as u64, bios_date) };
if i >= 0 {
return unsafe { (*data).orientation };
}
}
}
r#match = unsafe { dmi_first_match(r#match.wrapping_offset(1 as isize)) };
}
-1
}

